function hashOmenPayload(payload, depth, eventIndex) {
  const at = payload?.at || {};
  const text = [
    payload?.kind,
    payload?.medium,
    payload?.cause,
    payload?.sourceKind,
    payload?.identity,
    depth,
    Number(at.x) | 0,
    Number(at.y) | 0,
    eventIndex,
  ].join(":");
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

